{"content":"import { create } from 'zustand'
import { apiClient } from '../lib/apiClient'
import type {
  CreateDocumentRequest,
  CreateProjectRequest,
  Document,
  DocumentDiffResponse,
  DocumentListResponse,
  Project,
  ProjectListResponse,
} from '../types/api'
import { extractField } from '../lib/utils'

interface DocumentsState {
  projects: Project[]
  currentProjectId: string | null
  documents: Document[]
  currentDocId: string | null
  currentDoc: Document | null
  isLoading: boolean
  error: string | null
  showDeleted: boolean
  selectedDocIds: Set<string>

  fetchProjects: () => Promise<void>
  createProject: (name: string, notes?: string) => Promise<Project | null>
  setCurrentProject: (id: string | null) => void

  fetchDocuments: (projectId?: string | null) => Promise<void>
  createDocument: (name: string, notes?: string, sourceDocumentId?: string) => Promise<Document | null>
  copyDocument: (id: string, name?: string) => Promise<Document | null>
  fetchDocument: (id: string) => Promise<Document | null>
  setCurrentDoc: (id: string | null) => void
  updateLocalDoc: (id: string, updates: Partial<Document>) => void
  updateDocument: (id: string, updates: Partial<Document>) => Promise<boolean>
  deleteDocument: (id: string) => Promise<boolean>
  deleteMultipleDocuments: (ids: string[]) => Promise<void>
  getDiff: (leftId: string, rightId: string) => Promise<DocumentDiffResponse | null>

  setShowDeleted: (show: boolean) => void
  toggleDocSelection: (id: string) => void
  clearSelection: () => void
  selectAll: (docIds: string[]) => void
}

function normalizeProject(project: Partial<Project>): Project {
  const id = String(project.id || project.project_id || '')
  return {
    ...project,
    id,
    project_id: project.project_id ?? (id ? Number(id) : undefined),
    user_id: project.user_id ?? 0,
    name: project.name || '',
  } as Project
}

function normalizeDocument(document: Partial<Document>): Document {
  const id = String(document.id || document.document_id || '')
  return {
    ...document,
    id,
    document_id: document.document_id ?? (id ? Number(id) : undefined),
    project_id: document.project_id ?? 0,
    name: document.name || '',
  } as Document
}

export const useDocumentsStore = create<DocumentsState>((set, get) => ({
  projects: [],
  currentProjectId: null,
  documents: [],
  currentDocId: null,
  currentDoc: null,
  isLoading: false,
  error: null,
  showDeleted: false,
  selectedDocIds: new Set<string>(),

  fetchProjects: async () => {
    set({ isLoading: true, error: null })
    const response = await apiClient.get<ProjectListResponse>('/projects')

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to fetch projects',
      })
      return
    }

    const projects = extractField<Project[]>(
      response.data as Record<string, unknown>,
      'projects',
      'items',
      'data'
    ) || []

    const normalized = projects.map((project) => normalizeProject(project))
    const state = get()
    const nextProjectId =
      state.currentProjectId && normalized.some((project) => project.id === state.currentProjectId)
        ? state.currentProjectId
        : normalized[0]?.id || null

    set({
      projects: normalized,
      currentProjectId: nextProjectId,
      isLoading: false,
      error: null,
    })

    if (nextProjectId) {
      await get().fetchDocuments(nextProjectId)
    } else {
      set({ documents: [], currentDoc: null, currentDocId: null })
    }
  },

  createProject: async (name: string, notes?: string) => {
    set({ isLoading: true, error: null })
    const payload: CreateProjectRequest = { name, notes }

    const response = await apiClient.post<Project>('/projects', { body: payload })
    if (!response.ok || !response.data) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to create project',
      })
      return null
    }

    const project = normalizeProject(response.data)
    set((state) => ({
      projects: [project, ...state.projects],
      currentProjectId: project.id,
      isLoading: false,
      error: null,
    }))
    await get().fetchDocuments(project.id)
    return project
  },

  setCurrentProject: (id: string | null) => {
    set({
      currentProjectId: id,
      documents: [],
      currentDocId: null,
      currentDoc: null,
      selectedDocIds: new Set<string>(),
    })
    if (id) {
      get().fetchDocuments(id)
    }
  },

  fetchDocuments: async (projectId?: string | null) => {
    const targetProjectId = projectId ?? get().currentProjectId
    if (!targetProjectId) {
      set({ documents: [], currentDoc: null, currentDocId: null })
      return
    }

    set({ isLoading: true, error: null })
    const response = await apiClient.get<DocumentListResponse>(`/projects/${targetProjectId}/documents`, {
      params: { include_deleted: get().showDeleted },
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to fetch documents',
      })
      return
    }

    const documents = extractField<Document[]>(
      response.data as Record<string, unknown>,
      'documents',
      'items',
      'data'
    ) || []

    const normalized = documents.map((document) => normalizeDocument(document))
    const currentDoc = normalized.find((document) => document.id === get().currentDocId) || null

    set({
      documents: normalized,
      currentDoc,
      currentDocId: currentDoc?.id || null,
      isLoading: false,
      error: null,
    })
  },

  createDocument: async (name: string, notes?: string, sourceDocumentId?: string) => {
    const projectId = get().currentProjectId
    if (!projectId) {
      set({ error: 'Select a project first' })
      return null
    }

    set({ isLoading: true, error: null })
    const payload: CreateDocumentRequest = {
      project_id: Number(projectId),
      name,
      notes,
      source_document_id: sourceDocumentId ? Number(sourceDocumentId) : undefined,
    }

    const response = await apiClient.post<Document>('/documents', { body: payload })
    if (!response.ok || !response.data) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to create document',
      })
      return null
    }

    const document = normalizeDocument(response.data)
    set((state) => ({
      documents: [document, ...state.documents],
      currentDoc: document,
      currentDocId: document.id,
      isLoading: false,
      error: null,
    }))
    return document
  },

  copyDocument: async (id: string, name?: string) => {
    const response = await apiClient.post<Document>(`/documents/${id}/copy`, {
      body: { name },
    })
    if (!response.ok || !response.data) {
      set({ error: response.errorMessage || 'Failed to copy document' })
      return null
    }

    const copied = normalizeDocument(response.data)
    set((state) => ({
      documents: [copied, ...state.documents],
      currentDoc: copied,
      currentDocId: copied.id,
      error: null,
    }))
    return copied
  },

  fetchDocument: async (id: string) => {
    set({ isLoading: true, error: null })
    const response = await apiClient.get<Document>(`/documents/${id}`)

    if (!response.ok || !response.data) {
      set({
        isLoading: false,
        error: response.errorMessage || 'Failed to fetch document',
      })
      return null
    }

    const document = normalizeDocument(response.data)
    set({
      currentDoc: document,
      currentDocId: document.id,
      isLoading: false,
      error: null,
    })
    return document
  },

  setCurrentDoc: (id: string | null) => {
    if (id === null) {
      set({ currentDocId: null, currentDoc: null })
      return
    }
    const document = get().documents.find((entry) => entry.id === id)
    if (document) {
      set({ currentDocId: document.id, currentDoc: document })
      return
    }
    get().fetchDocument(id)
  },

  updateLocalDoc: (id: string, updates: Partial<Document>) => {
    set((state) => ({
      documents: state.documents.map((document) =>
        document.id === id ? { ...document, ...updates } : document
      ),
      currentDoc:
        state.currentDoc?.id === id ? { ...state.currentDoc, ...updates } : state.currentDoc,
    }))
  },

  updateDocument: async (id: string, updates: Partial<Document>) => {
    const response = await apiClient.patch<Document>(`/documents/${id}`, {
      body: updates,
    })

    if (!response.ok || !response.data) {
      set({ error: response.errorMessage || 'Failed to update document' })
      return false
    }

    const normalized = normalizeDocument(response.data)
    set((state) => ({
      documents: state.documents.map((document) =>
        document.id === id ? { ...document, ...normalized } : document
      ),
      currentDoc:
        state.currentDoc?.id === id ? { ...state.currentDoc, ...normalized } : state.currentDoc,
      error: null,
    }))
    return true
  },

  deleteDocument: async (id: string) => {
    const response = await apiClient.delete(`/documents/${id}`)
    if (!response.ok) {
      set({ error: response.errorMessage || 'Failed to delete document' })
      return false
    }
    await get().fetchDocuments()
    return true
  },

  deleteMultipleDocuments: async (ids: string[]) => {
    const requests = ids.map((id) => apiClient.delete(`/documents/${id}`))
    await Promise.all(requests)
    set({ selectedDocIds: new Set<string>() })
    await get().fetchDocuments()
  },

  getDiff: async (leftId: string, rightId: string) => {
    const response = await apiClient.get<DocumentDiffResponse>(`/documents/${leftId}/diff/${rightId}`)
    if (!response.ok || !response.data) {
      set({ error: response.errorMessage || 'Failed to diff documents' })
      return null
    }
    return response.data
  },

  setShowDeleted: (show: boolean) => {
    set({ showDeleted: show })
    get().fetchDocuments()
  },

  toggleDocSelection: (id: string) => {
    set((state) => {
      const updated = new Set(state.selectedDocIds)
      if (updated.has(id)) {
        updated.delete(id)
      } else {
        updated.add(id)
      }
      return { selectedDocIds: updated }
    })
  },

  clearSelection: () => {
    set({ selectedDocIds: new Set<string>() })
  },

  selectAll: (docIds: string[]) => {
    set({ selectedDocIds: new Set<string>(docIds) })
  },
}))
"}

{"content":"import { DragEvent, useMemo, useState } from 'react'
import { useDocumentsStore } from '../stores/useDocumentsStore'
import { useSessionStore } from '../stores/useSessionStore'
import { BLOCK_LIBRARY_TYPES, getBlockTypeIcon, getBlockTypeLabel } from '../lib/blockTypeMeta'
import type { ToolView } from './ToolsSwitcher'
import type { LibraryEditorView } from './editorPaneTypes'

interface ToolsPaneProps {
  activeView: ToolView | null
  libraryView: LibraryEditorView
  onLibraryViewChange: (view: LibraryEditorView) => void
  onInsertBlockType: (blockTypeId: string) => void
}

export default function ToolsPane({
  activeView,
  libraryView,
  onLibraryViewChange,
  onInsertBlockType,
}: ToolsPaneProps) {
  const [projectsFilter, setProjectsFilter] = useState('')
  const [documentsFilter, setDocumentsFilter] = useState('')
  const [showProjectModal, setShowProjectModal] = useState(false)
  const [showNewDocModal, setShowNewDocModal] = useState(false)
  const [showCopyModal, setShowCopyModal] = useState(false)
  const [newProjectName, setNewProjectName] = useState('')
  const [newDocName, setNewDocName] = useState('')
  const [copySourceDocId, setCopySourceDocId] = useState('')
  const [copyName, setCopyName] = useState('')
  const [isCreatingProject, setIsCreatingProject] = useState(false)
  const [isCreatingDocument, setIsCreatingDocument] = useState(false)
  const [isCopyingDocument, setIsCopyingDocument] = useState(false)

  const {
    projects,
    currentProjectId,
    setCurrentProject,
    createProject,
    documents,
    currentDocId,
    setCurrentDoc,
    createDocument,
    copyDocument,
    isLoading,
  } = useDocumentsStore()

  const { user, baseUrl, logout } = useSessionStore()

  const filteredProjects = useMemo(() => {
    const needle = projectsFilter.trim().toLowerCase()
    if (!needle) {
      return projects
    }
    return projects.filter((project) => project.name.toLowerCase().includes(needle))
  }, [projects, projectsFilter])

  const filteredDocuments = useMemo(() => {
    const needle = documentsFilter.trim().toLowerCase()
    if (!needle) {
      return documents
    }
    return documents.filter((entry) => entry.name.toLowerCase().includes(needle))
  }, [documents, documentsFilter])

  const openCopyModal = () => {
    setCopySourceDocId(currentDocId || documents[0]?.id || '')
    setCopyName('')
    setShowCopyModal(true)
  }

  const createProjectFromModal = async (event: React.FormEvent) => {
    event.preventDefault()
    const trimmedName = newProjectName.trim()
    if (!trimmedName) {
      return
    }

    setIsCreatingProject(true)
    const created = await createProject(trimmedName)
    setIsCreatingProject(false)

    if (created) {
      setNewProjectName('')
      setShowProjectModal(false)
    }
  }

  const createDocumentFromModal = async (event: React.FormEvent) => {
    event.preventDefault()
    const trimmedName = newDocName.trim()
    if (!trimmedName) {
      return
    }

    setIsCreatingDocument(true)
    const created = await createDocument(trimmedName)
    setIsCreatingDocument(false)

    if (created) {
      setCurrentDoc(created.id)
      setNewDocName('')
      setShowNewDocModal(false)
    }
  }

  const copyDocumentFromModal = async (event: React.FormEvent) => {
    event.preventDefault()
    if (!copySourceDocId) {
      return
    }

    setIsCopyingDocument(true)
    const copied = await copyDocument(copySourceDocId, copyName.trim() || undefined)
    setIsCopyingDocument(false)

    if (copied) {
      setCurrentDoc(copied.id)
      setShowCopyModal(false)
    }
  }

  const handleBlockDragStart = (event: DragEvent<HTMLButtonElement>, blockTypeId: string) => {
    event.dataTransfer.setData('application/x-forgelab-block-type', blockTypeId)
    event.dataTransfer.effectAllowed = 'copy'
  }

  if (!activeView) {
    return null
  }

  return (
    <aside className="ui-pane w-80">
      <div className="ui-pane-header">
        <h2 className="ui-pane-title">
          {activeView === 'projects' && 'Projects'}
          {activeView === 'documents' && 'Documents'}
          {activeView === 'blocks' && 'Blocks'}
          {activeView === 'library' && 'Library'}
          {activeView === 'users' && 'Users'}
        </h2>
      </div>

      {activeView === 'projects' && (
        <div className="ui-pane-body">
          <div className="flex gap-2">
            <input
              type="text"
              value={projectsFilter}
              onChange={(event) => setProjectsFilter(event.target.value)}
              placeholder="Filter projects..."
              className="ui-input flex-1"
            />
            <button
              type="button"
              onClick={() => setShowProjectModal(true)}
              className="ui-btn"
            >
              Create new
            </button>
          </div>

          <div className="space-y-2">
            {filteredProjects.length === 0 ? (
              <div className="text-sm text-gray-500">No projects found.</div>
            ) : (
              filteredProjects.map((project) => {
                const isActive = project.id === currentProjectId
                return (
                  <button
                    key={project.id}
                    type="button"
                    onClick={() => setCurrentProject(project.id)}
                    className={`ui-list-item ${isActive ? 'ui-list-item-active' : ''}`}
                  >
                    <div className="font-medium text-sm truncate">{project.name}</div>
                    <div className="text-xs text-gray-500">ID: {project.project_id || project.id}</div>
                  </button>
                )
              })
            )}
          </div>
        </div>
      )}

      {activeView === 'documents' && (
        <div className="ui-pane-body">
          <div className="text-xs text-gray-500">
            Current project:{' '}
            <span className="font-medium text-gray-700">{currentProjectId || 'None selected'}</span>
          </div>

          <div className="flex gap-2">
            <input
              type="text"
              value={documentsFilter}
              onChange={(event) => setDocumentsFilter(event.target.value)}
              placeholder="Filter documents..."
              className="ui-input flex-1"
              disabled={!currentProjectId}
            />
          </div>

          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => setShowNewDocModal(true)}
              disabled={!currentProjectId}
              className="ui-btn-primary flex-1"
            >
              New
            </button>
            <button
              type="button"
              onClick={openCopyModal}
              disabled={!currentProjectId || documents.length === 0}
              className="ui-btn-secondary flex-1"
            >
              Copy
            </button>
          </div>

          <div className="space-y-2">
            {isLoading && documents.length === 0 ? (
              <div className="text-sm text-gray-500">Loading documents...</div>
            ) : filteredDocuments.length === 0 ? (
              <div className="text-sm text-gray-500">No documents in this project.</div>
            ) : (
              filteredDocuments.map((entry) => {
                const entryId = String(entry.id)
                const isActive = currentDocId === entryId

                return (
                  <button
                    key={entryId}
                    type="button"
                    onClick={() => setCurrentDoc(entryId)}
                    className={`ui-list-item ${isActive ? 'ui-list-item-active' : ''}`}
                  >
                    <div className="font-medium text-sm truncate">{entry.name}</div>
                    <div className="text-xs text-gray-500">
                      ID: {entry.document_id || entry.id}
                      {entry.source_document_id ? ` | copy of ${entry.source_document_id}` : ''}
                    </div>
                  </button>
                )
              })
            )}
          </div>
        </div>
      )}

      {activeView === 'blocks' && (
        <div className="ui-pane-body">
          <div className="text-xs text-gray-500">
            Drag a block type into BlockEditor or use Insert.
          </div>

          <div className="space-y-2">
            {BLOCK_LIBRARY_TYPES.map((entry) => (
              <div key={entry.id} className="ui-card ui-card-body flex items-center gap-2">
                <button
                  type="button"
                  draggable
                  onDragStart={(event) => handleBlockDragStart(event, entry.id)}
                  className="ui-btn w-10 h-10 p-0 font-semibold"
                  title={`Drag ${getBlockTypeLabel(entry.id)}`}
                >
                  {getBlockTypeIcon(entry.id)}
                </button>
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-medium truncate">{getBlockTypeLabel(entry.id)}</div>
                  <div className="text-xs text-gray-500">{entry.id}</div>
                </div>
                <button
                  type="button"
                  onClick={() => onInsertBlockType(entry.id)}
                  className="ui-btn"
                >
                  Insert
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeView === 'library' && (
        <div className="ui-pane-body">
          <div className="text-xs text-gray-500">
            Select Library editor view.
          </div>
          <div className="space-y-2">
            <button
              type="button"
              onClick={() => onLibraryViewChange('dies')}
              className={`ui-list-item ${libraryView === 'dies' ? 'ui-list-item-active' : ''}`}
            >
              Dies
            </button>
            <button
              type="button"
              onClick={() => onLibraryViewChange('dieAssemblies')}
              className={`ui-list-item ${libraryView === 'dieAssemblies' ? 'ui-list-item-active' : ''}`}
            >
              Die Assemblies
            </button>
            <button
              type="button"
              onClick={() => onLibraryViewChange('presses')}
              className={`ui-list-item ${libraryView === 'presses' ? 'ui-list-item-active' : ''}`}
            >
              Presses
            </button>
          </div>
        </div>
      )}

      {activeView === 'users' && (
        <div className="ui-pane-body space-y-3">
          <div className="ui-card ui-card-body">
            <div className="text-xs uppercase tracking-wide text-gray-500 mb-1">Current User</div>
            {user ? (
              <>
                <div className="font-medium text-sm text-gray-900">{user.login}</div>
                <div className="text-sm text-gray-600">{user.email}</div>
                <div className="text-xs text-gray-500 mt-1">ID: {user.user_id}</div>
              </>
            ) : (
              <div className="text-sm text-gray-500">No user loaded.</div>
            )}
          </div>

          <div className="ui-card ui-card-body">
            <div className="text-xs uppercase tracking-wide text-gray-500 mb-1">Connection</div>
            <div className="text-sm text-gray-700 break-all">{baseUrl}</div>
          </div>

          <button
            type="button"
            onClick={logout}
            className="ui-btn w-full"
          >
            Logout
          </button>
        </div>
      )}

      {showProjectModal && (
        <div className="ui-modal-overlay">
          <div className="ui-modal w-96">
            <h3 className="ui-pane-title mb-3">Create Project</h3>
            <form onSubmit={createProjectFromModal}>
              <input
                type="text"
                value={newProjectName}
                onChange={(event) => setNewProjectName(event.target.value)}
                placeholder="Project name..."
                className="ui-input mb-3"
                autoFocus
                disabled={isCreatingProject}
              />
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setShowProjectModal(false)}
                  className="ui-btn"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isCreatingProject || !newProjectName.trim()}
                  className="ui-btn-primary"
                >
                  {isCreatingProject ? 'Creating...' : 'Create'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showNewDocModal && (
        <div className="ui-modal-overlay">
          <div className="ui-modal w-96">
            <h3 className="ui-pane-title mb-3">Create Document</h3>
            <form onSubmit={createDocumentFromModal}>
              <input
                type="text"
                value={newDocName}
                onChange={(event) => setNewDocName(event.target.value)}
                placeholder="Document name..."
                className="ui-input mb-3"
                autoFocus
                disabled={isCreatingDocument}
              />
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setShowNewDocModal(false)}
                  className="ui-btn"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isCreatingDocument || !newDocName.trim() || !currentProjectId}
                  className="ui-btn-primary"
                >
                  {isCreatingDocument ? 'Creating...' : 'Create'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showCopyModal && (
        <div className="ui-modal-overlay">
          <div className="ui-modal w-96">
            <h3 className="ui-pane-title mb-3">Copy Document</h3>
            <form onSubmit={copyDocumentFromModal} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Source</label>
                <select
                  value={copySourceDocId}
                  onChange={(event) => setCopySourceDocId(event.target.value)}
                  className="ui-select"
                >
                  <option value="">Select source document...</option>
                  {documents.map((entry) => (
                    <option key={entry.id} value={entry.id}>
                      {entry.name}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">
                  New name (optional)
                </label>
                <input
                  type="text"
                  value={copyName}
                  onChange={(event) => setCopyName(event.target.value)}
                  placeholder="Copied document name..."
                  className="ui-input"
                />
              </div>

              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setShowCopyModal(false)}
                  className="ui-btn"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isCopyingDocument || !copySourceDocId}
                  className="ui-btn-secondary"
                >
                  {isCopyingDocument ? 'Copying...' : 'Copy'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </aside>
  )
}
"}

{"content":"import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

import DieStlPreview from './DieStlPreview'
import { formatLibraryName, formatTimestamp } from '../../lib/libraryDisplay'
import type {
  DieAssemblyRecord,
  DieRecord,
  DieTypeRecord,
  LibraryDbUserRecord,
  PressModeRecord,
  PressRecord,
} from '../../types/api'

type OwnerFilterKey =
  | 'all'
  | 'builtIn'
  | 'builtInAndCurrentUser'
  | 'allUsers'
  | 'currentUser'
  | 'selectedUser'

const OWNER_FILTER_ITEMS: Array<{ id: OwnerFilterKey; label: string }> = [
  { id: 'all', label: 'All' },
  { id: 'builtIn', label: 'Build-in' },
  { id: 'builtInAndCurrentUser', label: 'Build-in and Current user' },
  { id: 'allUsers', label: 'All users' },
  { id: 'currentUser', label: 'Current user' },
  { id: 'selectedUser', label: 'Selected user' },
]

const DEFAULT_OWNER_FILTERS: Set<OwnerFilterKey> = new Set(['builtInAndCurrentUser'])

function toggleFilter<T>(current: Set<T>, value: T): Set<T> {
  if (current.has(value)) {
    if (current.size === 1) {
      return current
    }
    const next = new Set(current)
    next.delete(value)
    return next
  }

  const next = new Set(current)
  next.add(value)
  return next
}

function normalizeNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value
  }

  if (typeof value === 'string' && value.trim().length > 0) {
    const parsed = Number(value)
    if (Number.isFinite(parsed)) {
      return parsed
    }
  }

  return null
}

function buildUserLabel(user: LibraryDbUserRecord): string {
  if (user.full_name && user.full_name.trim().length > 0) {
    return user.full_name
  }
  return user.login
}

function getOwnerLabel(ownerUserId: number | null | undefined, usersById: Map<number, LibraryDbUserRecord>): string {
  if (ownerUserId === null || ownerUserId === undefined) {
    return 'Build-in'
  }

  const user = usersById.get(ownerUserId)
  if (!user) {
    return `User ${ownerUserId}`
  }

  return `${buildUserLabel(user)} (${user.login})`
}

function matchesOwnerFilter(
  ownerUserId: number | null | undefined,
  activeOwnerFilters: Set<OwnerFilterKey>,
  currentUserId: number | null,
  selectedUserId: number | null
): boolean {
  if (activeOwnerFilters.has('all')) {
    return true
  }

  let matches = false

  if (activeOwnerFilters.has('builtIn')) {
    matches = matches || ownerUserId === 1
  }

  if (activeOwnerFilters.has('builtInAndCurrentUser')) {
    matches =
      matches ||
      ownerUserId === 1 ||
      (currentUserId !== null && ownerUserId === currentUserId)
  }

  if (activeOwnerFilters.has('allUsers')) {
    matches = matches || ownerUserId !== 1
  }

  if (activeOwnerFilters.has('currentUser')) {
    matches = matches || (currentUserId !== null && ownerUserId === currentUserId)
  }

  if (activeOwnerFilters.has('selectedUser')) {
    matches = matches || (selectedUserId !== null && ownerUserId === selectedUserId)
  }

  return matches
}

function useSelectedUserState(
  users: LibraryDbUserRecord[],
  currentUserId: number | null
): [number | null, (nextUserId: number) => void] {
  const [selectedUserId, setSelectedUserId] = useState<number | null>(currentUserId)

  useEffect(() => {
    if (users.length === 0) {
      setSelectedUserId(null)
      return
    }

    setSelectedUserId((previous) => {
      if (previous !== null && users.some((entry) => entry.user_id === previous)) {
        return previous
      }

      if (currentUserId !== null && users.some((entry) => entry.user_id === currentUserId)) {
        return currentUserId
      }

      return users[0].user_id
    })
  }, [currentUserId, users])

  const setSelected = (nextUserId: number) => {
    setSelectedUserId(nextUserId)
  }

  return [selectedUserId, setSelected]
}

function OwnerFilters({
  activeOwnerFilters,
  onToggleOwnerFilter,
  users,
  selectedUserId,
  onSelectedUserChange,
}: {
  activeOwnerFilters: Set<OwnerFilterKey>
