{"content":"import { useMemo, useState } from 'react'
import { Link } from 'react-router-dom'

import { apiClient } from '../lib/apiClient'
import type {
  ResetAdminPasswordRequest,
  ResetAdminPasswordResponse,
  SeedLibraryResponse,
  SetupStatusResponse,
} from '../types/api'

interface SetupPageProps {
  status: SetupStatusResponse | null
  isStatusLoading: boolean
  isAuthenticated: boolean
  onRefreshStatus: () => Promise<void>
}

export default function SetupPage({
  status,
  isStatusLoading,
  isAuthenticated,
  onRefreshStatus,
}: SetupPageProps) {
  const [isSeeding, setIsSeeding] = useState(false)
  const [seedError, setSeedError] = useState<string | null>(null)
  const [seedSuccess, setSeedSuccess] = useState<string | null>(null)
  const [newAdminPassword, setNewAdminPassword] = useState('')
  const [confirmAdminPassword, setConfirmAdminPassword] = useState('')
  const [isResettingAdminPassword, setIsResettingAdminPassword] = useState(false)
  const [resetAdminPasswordError, setResetAdminPasswordError] = useState<string | null>(null)
  const [resetAdminPasswordSuccess, setResetAdminPasswordSuccess] = useState<string | null>(null)

  const canSeed = useMemo(() => {
    if (!status) {
      return false
    }
    if (status.can_seed_without_auth) {
      return true
    }
    return isAuthenticated
  }, [status, isAuthenticated])

  const handleSeed = async () => {
    setSeedError(null)
    setSeedSuccess(null)
    setIsSeeding(true)

    const response = await apiClient.post<SeedLibraryResponse>('/setup/seed-library')
    setIsSeeding(false)

    if (!response.ok || !response.data) {
      setSeedError(response.errorMessage || 'Failed to seed library')
      return
    }

    setSeedSuccess(`Seed completed (run #${response.data.run_id}).`)
    await onRefreshStatus()
  }

  const handleResetAdminPassword = async () => {
    setResetAdminPasswordError(null)
    setResetAdminPasswordSuccess(null)

    if (!newAdminPassword || newAdminPassword.length < 8) {
      setResetAdminPasswordError('Password must be at least 8 characters.')
      return
    }
    if (newAdminPassword !== confirmAdminPassword) {
      setResetAdminPasswordError('Password confirmation does not match.')
      return
    }

    setIsResettingAdminPassword(true)
    const response = await apiClient.post<ResetAdminPasswordResponse>('/setup/reset-admin-password', {
      body: {
        new_password: newAdminPassword,
      } satisfies ResetAdminPasswordRequest,
    })
    setIsResettingAdminPassword(false)

    if (!response.ok || !response.data) {
      setResetAdminPasswordError(response.errorMessage || 'Failed to reset admin password.')
      return
    }

    setResetAdminPasswordSuccess(`Password updated for user '${response.data.login}'.`)
    setNewAdminPassword('')
    setConfirmAdminPassword('')
  }

  return (
    <div className="ui-shell min-h-screen p-4">
      <div className="max-w-3xl mx-auto space-y-3">
        <div className="ui-card ui-card-body">
          <h1 className="text-sm font-semibold text-gray-900">Setup & Seeding</h1>
          <p className="text-xs text-gray-600 mt-1">
            Use this page on first launch, or run seeding again as an administrator.
          </p>
        </div>

        <div className="ui-card ui-card-body space-y-3">
          <div className="flex items-center gap-2">
            <button
              type="button"
              className="ui-btn"
              onClick={() => void onRefreshStatus()}
              disabled={isStatusLoading}
            >
              {isStatusLoading ? 'Refreshing...' : 'Refresh Status'}
            </button>
            <button
              type="button"
              className="ui-btn-primary"
              onClick={handleSeed}
              disabled={!canSeed || isSeeding || isStatusLoading}
            >
              {isSeeding ? 'Seeding...' : 'Run Library Seed'}
            </button>
            <Link className="ui-btn" to="/app">
              Open App
            </Link>
            {!isAuthenticated && (
              <Link className="ui-btn" to="/login">
                Login
              </Link>
            )}
          </div>

          {!canSeed && (
            <div className="text-xs text-amber-700 border border-amber-300 bg-amber-50 rounded p-2">
              Administrator login is required to seed this environment.
            </div>
          )}

          {seedError && (
            <div className="text-xs text-red-700 border border-red-300 bg-red-50 rounded p-2">
              {seedError}
            </div>
          )}
          {seedSuccess && (
            <div className="text-xs text-green-700 border border-green-300 bg-green-50 rounded p-2">
              {seedSuccess}
            </div>
          )}
        </div>

        <div className="ui-card ui-card-body">
          <div className="text-xs text-gray-700 space-y-1">
            <div>Needs seed: {status?.needs_seed ? 'yes' : 'no'}</div>
            <div>Can seed without auth: {status?.can_seed_without_auth ? 'yes' : 'no'}</div>
            <div>Config file exists: {status?.file_exists ? 'yes' : 'no'}</div>
            <div>Config hash: {status?.file_hash || 'n/a'}</div>
          </div>
        </div>

        <div className="ui-card ui-card-body">
          <h2 className="text-xs font-semibold text-gray-900 mb-2">Table Counts</h2>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 text-xs">
            {Object.entries(status?.counts || {}).map(([tableName, count]) => (
              <div key={tableName} className="ui-badge flex items-center justify-between">
                <span>{tableName}</span>
                <span>{count}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="ui-card ui-card-body space-y-3">
          <h2 className="text-xs font-semibold text-gray-900">Admin Password</h2>
          <p className="text-xs text-gray-600">
            Reset password for account <span className="font-semibold">admin</span>.
          </p>

          {!isAuthenticated && (
            <div className="text-xs text-amber-700 border border-amber-300 bg-amber-50 rounded p-2">
              Login as administrator to reset admin password.
            </div>
          )}

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            <input
              type="password"
              className="ui-input"
              placeholder="New admin password"
              value={newAdminPassword}
              onChange={(e) => setNewAdminPassword(e.target.value)}
              disabled={!isAuthenticated || isResettingAdminPassword}
            />
            <input
              type="password"
              className="ui-input"
              placeholder="Confirm new password"
              value={confirmAdminPassword}
              onChange={(e) => setConfirmAdminPassword(e.target.value)}
              disabled={!isAuthenticated || isResettingAdminPassword}
            />
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              className="ui-btn-secondary"
              disabled={!isAuthenticated || isResettingAdminPassword}
              onClick={handleResetAdminPassword}
            >
              {isResettingAdminPassword ? 'Updating...' : 'Reset Admin Password'}
            </button>
          </div>

          {resetAdminPasswordError && (
            <div className="text-xs text-red-700 border border-red-300 bg-red-50 rounded p-2">
              {resetAdminPasswordError}
            </div>
          )}
          {resetAdminPasswordSuccess && (
            <div className="text-xs text-green-700 border border-green-300 bg-green-50 rounded p-2">
              {resetAdminPasswordSuccess}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
"}

{"content":"import type { ApiResponse } from '../types/api'

type QueryParams = Record<string, string | number | boolean | null | undefined>

interface RequestOptions {
  params?: QueryParams
  body?: unknown
  headers?: Record<string, string>
}

type HttpMethod = 'GET' | 'POST' | 'PATCH' | 'DELETE'

const LOOPBACK_DEFAULT_BASE_URL = 'http://127.0.0.1:8001'
const LOOPBACK_HOSTNAMES = new Set(['127.0.0.1', 'localhost', '::1'])
const viteEnv = (
  import.meta as { env?: Record<string, string | boolean | undefined> }
).env
const isDevMode = viteEnv?.DEV === true || viteEnv?.MODE === 'development'

function normalizeApiBaseUrl(url: string): string {
  if (!url) {
    return ''
  }

  const trimmed = url.trim().replace(/\/+$/, '')
  if (!trimmed) {
    return ''
  }

  if (!isDevMode) {
    return trimmed
  }

  try {
    const parsed = new URL(trimmed)
    if (LOOPBACK_HOSTNAMES.has(parsed.hostname.toLowerCase())) {
      return parsed.origin
    }
  } catch {
    return LOOPBACK_DEFAULT_BASE_URL
  }

  return LOOPBACK_DEFAULT_BASE_URL
}

function formatErrorDetail(detail: unknown): string | undefined {
  if (typeof detail === 'string') {
    return detail
  }

  if (Array.isArray(detail)) {
    const lines = detail
      .map((entry) => {
        if (!entry || typeof entry !== 'object') {
          return String(entry)
        }

        const record = entry as Record<string, unknown>
        const message =
          (typeof record.msg === 'string' && record.msg) ||
          (typeof record.message === 'string' && record.message) ||
          (typeof record.error === 'string' && record.error) ||
          ''

        const location = Array.isArray(record.loc)
          ? record.loc
              .filter((token): token is string | number => typeof token === 'string' || typeof token === 'number')
              .map(String)
              .filter((token) => token !== 'body' && token !== 'query' && token !== 'path')
              .join('.')
          : ''

        if (location && message) {
          return `${location}: ${message}`
        }

        if (message) {
          return message
        }

        return JSON.stringify(record)
      })
      .filter((line) => line && line.trim().length > 0)

    return lines.length > 0 ? lines.join('\n') : undefined
  }

  if (detail && typeof detail === 'object') {
    const record = detail as Record<string, unknown>
    return (
      (typeof record.message === 'string' && record.message) ||
      (typeof record.error === 'string' && record.error) ||
      JSON.stringify(record)
    )
  }

  return undefined
}

class ApiClient {
  private baseUrl: string
  private token: string | null = null
  private onUnauthenticated: (() => void) | null = null

  constructor(baseUrl: string) {
    this.baseUrl = this.normalizeBaseUrl(baseUrl)
  }

  setBaseUrl(url: string): void {
    this.baseUrl = this.normalizeBaseUrl(url)
  }

  getBaseUrl(): string {
    return this.baseUrl
  }

  setToken(token: string | null): void {
    this.token = token
  }

  getToken(): string | null {
    return this.token
  }

  setOnUnauthenticated(callback: (() => void) | null): void {
    this.onUnauthenticated = callback
  }

  async get<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('GET', path, options)
  }

  async post<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('POST', path, options)
  }

  async patch<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('PATCH', path, options)
  }

  async delete<T>(path: string, options?: RequestOptions): Promise<ApiResponse<T>> {
    return this.request<T>('DELETE', path, options)
  }

  private async request<T>(
    method: HttpMethod,
    path: string,
    options?: RequestOptions
  ): Promise<ApiResponse<T>> {
    const url = this.buildUrl(path, options?.params)
    const headers: Record<string, string> = {
      ...(options?.headers || {}),
    }

    if (this.token) {
      headers.Authorization = `Bearer ${this.token}`
    }

    let body: string | undefined
    if (options?.body !== undefined) {
      if (!headers['Content-Type']) {
        headers['Content-Type'] = 'application/json'
      }
      body = JSON.stringify(options.body)
    }

    try {
      const response = await fetch(url, {
        method,
        headers,
        body,
      })

      if (response.status === 401 && this.onUnauthenticated) {
        this.onUnauthenticated()
      }

      const parsed = await this.parseResponse(response)
      return parsed as ApiResponse<T>
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Network error'
      return {
        ok: false,
        status: 0,
        errorMessage: message,
      }
    }
  }

  private async parseResponse(response: Response): Promise<ApiResponse<unknown>> {
    const status = response.status
    let data: unknown = undefined
    let errorMessage: string | undefined = undefined
    let errorCode: string | undefined = undefined

    const text = await response.text()
    if (text) {
      try {
        data = JSON.parse(text)
      } catch {
        data = text
      }
    }

    if (!response.ok) {
      if (typeof data === 'string') {
        errorMessage = data
      } else if (data && typeof data === 'object') {
        const dataObj = data as Record<string, unknown>
        errorMessage =
          formatErrorDetail(dataObj.detail) ||
          (typeof dataObj.message === 'string' && dataObj.message) ||
          (typeof dataObj.error === 'string' && dataObj.error) ||
          undefined
        errorCode =
          (typeof dataObj.code === 'string' && dataObj.code) ||
          (typeof dataObj.error_code === 'string' && dataObj.error_code) ||
          undefined
      }
    }

    return {
      ok: response.ok,
      status,
      data: response.ok ? data : undefined,
      errorMessage,
      errorCode,
    }
  }

  private buildUrl(path: string, params?: QueryParams): string {
    const baseUrl = this.baseUrl || ''
    const url = new URL(path, baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`)

    if (params) {
      Object.entries(params).forEach(([key, value]) => {
        if (value === undefined || value === null) {
          return
        }
        url.searchParams.append(key, String(value))
      })
    }

    return url.toString()
  }

  private normalizeBaseUrl(url: string): string {
    return normalizeApiBaseUrl(url)
  }
}

const envBaseUrl = (viteEnv?.VITE_API_BASE_URL as string | undefined) || ''

const defaultBaseUrl = normalizeApiBaseUrl(envBaseUrl || LOOPBACK_DEFAULT_BASE_URL)

export const apiClient = new ApiClient(defaultBaseUrl)
"}

{"content":"from typing import Optional

from fastapi import APIRouter, Depends, HTTPException, status
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from jose import JWTError, jwt
from pydantic import BaseModel, Field
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.auth import get_password_hash
from app.config import settings
from app.database import get_db
from app.models.user import User
from app.services.library_seed_service import LibrarySeedError, library_seed_service

router = APIRouter(prefix="/setup", tags=["setup"])
optional_bearer = HTTPBearer(auto_error=False)


class AdminPasswordResetRequest(BaseModel):
    new_password: str = Field(min_length=8, max_length=255)


def _get_optional_user(
    credentials: Optional[HTTPAuthorizationCredentials] = Depends(optional_bearer),
    db: Session = Depends(get_db),
) -> Optional[User]:
    if credentials is None:
        return None

    token = credentials.credentials
    try:
        payload = jwt.decode(token, settings.SECRET_KEY, algorithms=[settings.ALGORITHM])
        user_id = int(payload.get("sub"))
    except (JWTError, TypeError, ValueError):
        return None

    return db.execute(select(User).filter(User.user_id == user_id)).scalars().first()


@router.get("/status")
def setup_status(
    db: Session = Depends(get_db),
):
    return library_seed_service.get_status(db)


@router.post("/seed-library")
def seed_library(
    only_missing: bool = False,
    db: Session = Depends(get_db),
    current_user: Optional[User] = Depends(_get_optional_user),
):
    setup_data = library_seed_service.get_status(db)
    users_count = int(setup_data.get("counts", {}).get("users", 0))

    # First install bootstrap: allow seeding without auth only when users table is empty.
    if users_count > 0 and (current_user is None or current_user.supervisor_id != 1):
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Administrator authentication is required to run library seeding",
        )

    try:
        return library_seed_service.seed_library(
            db,
            only_missing=only_missing,
            triggered_by_user_id=current_user.user_id if current_user else None,
        )
    except LibrarySeedError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@router.post("/reset-admin-password")
def reset_admin_password(
    payload: AdminPasswordResetRequest,
    db: Session = Depends(get_db),
    current_user: Optional[User] = Depends(_get_optional_user),
):
    if current_user is None or current_user.supervisor_id != 1:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Administrator authentication is required to reset admin password",
        )

    admin_user = db.execute(select(User).filter(User.login == "admin")).scalars().first()
    if admin_user is None:
        admin_user = db.execute(select(User).filter(User.user_id == 1)).scalars().first()
    if admin_user is None:
        raise HTTPException(status_code=404, detail="Admin user not found")

    admin_user.password_hashed = get_password_hash(payload.new_password)
    db.add(admin_user)
    db.commit()

    return {
        "ok": True,
        "user_id": admin_user.user_id,
        "login": admin_user.login,
        "message": "Admin password updated",
    }
"}

{"content":"import { useCallback, useEffect, useState } from 'react'
import { Routes, Route, Navigate } from 'react-router-dom'
import { useSessionStore } from './stores/useSessionStore'
import { apiClient } from './lib/apiClient'
import type { SetupStatusResponse } from './types/api'
import LoginPage from './pages/LoginPage'
import AppPage from './pages/AppPage'
import SetupPage from './pages/SetupPage'

function App() {
  const { isAuthenticated, initialize, logout } = useSessionStore()
  const [setupStatus, setSetupStatus] = useState<SetupStatusResponse | null>(null)
  const [isSetupLoading, setIsSetupLoading] = useState(true)

  const refreshSetupStatus = useCallback(async () => {
    setIsSetupLoading(true)
    const response = await apiClient.get<SetupStatusResponse>('/setup/status')
    if (response.ok && response.data) {
      setSetupStatus(response.data)
    } else {
      setSetupStatus(null)
    }
    setIsSetupLoading(false)
  }, [])

  useEffect(() => {
    initialize()
    void refreshSetupStatus()

    // Set up global authentication error handler
    apiClient.setOnUnauthenticated(() => {
      logout()
      // The Navigate will happen automatically due to isAuthenticated changing
    })
  }, [initialize, logout, refreshSetupStatus])

  if (isSetupLoading) {
    return (
      <div className="ui-shell min-h-screen flex items-center justify-center text-sm text-gray-600">
        Checking setup status...
      </div>
    )
  }

  const needsSetup = setupStatus?.needs_seed ?? true

  return (
    <Routes>
      <Route
        path="/setup"
        element={(
          <SetupPage
            status={setupStatus}
            isStatusLoading={isSetupLoading}
            isAuthenticated={isAuthenticated}
            onRefreshStatus={refreshSetupStatus}
          />
        )}
      />
      <Route
        path="/login"
        element={!isAuthenticated ? <LoginPage /> : <Navigate to={needsSetup ? '/setup' : '/app'} />}
      />
      <Route
        path="/app/*"
        element={needsSetup ? <Navigate to="/setup" /> : (isAuthenticated ? <AppPage /> : <Navigate to="/login" />)}
      />
      <Route path="/" element={<Navigate to={needsSetup ? '/setup' : '/app'} />} />
    </Routes>
  )
}

export default App
"}

{"content":"import { create } from 'zustand'
import { apiClient } from '../lib/apiClient'
import type { User, LoginRequest, LoginResponse, RegisterRequest } from '../types/api'
import { extractField } from '../lib/utils'

interface SessionState {
  token: string | null
  user: User | null
  baseUrl: string
  isAuthenticated: boolean
  isLoading: boolean
  error: string | null

  setBaseUrl: (url: string) => void
  login: (credentials: LoginRequest) => Promise<boolean>
  register: (data: RegisterRequest) => Promise<boolean>
  logout: () => void
  fetchMe: () => Promise<boolean>
  initialize: () => void
}

const TOKEN_KEY = 'forgelab-token'
const BASE_URL_KEY = 'forgelab-base-url'
const DEFAULT_BASE_URL = 'http://127.0.0.1:8001'

function buildAuthErrorMessage(
  mode: 'login' | 'register',
  errorMessage: string | undefined,
  status: number
): string {
  const message = (errorMessage || '').trim()

  if (!message) {
    if (status === 0) {
      return 'Cannot reach API server. Check API Settings and server connection.'
    }

    return mode === 'register'
      ? 'Registration failed. Check input fields and try again.'
      : 'Login failed. Check credentials and try again.'
  }

  const normalized = message.toLowerCase()

  if (mode === 'register') {
    if (normalized.includes('login already registered')) {
      return 'Username is already registered.\nUse a different username or sign in to the existing account.'
    }

    if (normalized.includes('email already registered')) {
      return 'Email is already registered.\nUse a different email or sign in to the existing account.'
    }

    if (status === 422) {
      return `Registration validation failed:\n${message}`
    }
  }

  if (mode === 'login' && normalized.includes('incorrect username or password')) {
    return 'Incorrect username or password.'
  }

  return message
}

export const useSessionStore = create<SessionState>((set, get) => ({
  token: null,
  user: null,
  baseUrl: DEFAULT_BASE_URL,
  isAuthenticated: false,
  isLoading: false,
  error: null,

  setBaseUrl: (url: string) => {
    apiClient.setBaseUrl(url)
    const normalizedBaseUrl = apiClient.getBaseUrl()
    localStorage.setItem(BASE_URL_KEY, normalizedBaseUrl)
    set({ baseUrl: normalizedBaseUrl })
  },

  login: async (credentials: LoginRequest) => {
    set({ isLoading: true, error: null })

    const response = await apiClient.post<LoginResponse>('/auth/login', {
      body: credentials,
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: buildAuthErrorMessage('login', response.errorMessage, response.status),
      })
      return false
    }

    // Extract token from response (tolerant)
    const token = extractField<string>(
      response.data as Record<string, unknown>,
      'access_token',
      'token',
      'accessToken'
    )

    if (!token) {
      set({ isLoading: false, error: 'No token received from server' })
      return false
    }

    // Save token
    localStorage.setItem(TOKEN_KEY, token)
    apiClient.setToken(token)
    set({ token, isAuthenticated: true })

    // Fetch user info
    const success = await get().fetchMe()
    set({ isLoading: false })
    return success
  },

  register: async (data: RegisterRequest) => {
    set({ isLoading: true, error: null })

    const response = await apiClient.post<User>('/auth/register', {
      body: data,
    })

    if (!response.ok) {
      set({
        isLoading: false,
        error: buildAuthErrorMessage('register', response.errorMessage, response.status),
      })
      return false
    }

    // After successful registration, automatically log in
    set({ isLoading: false })
    return get().login({ login: data.login, password: data.password })
  },

  logout: () => {
    localStorage.removeItem(TOKEN_KEY)
    apiClient.setToken(null)
    set({
      token: null,
      user: null,
      isAuthenticated: false,
      error: null,
    })
  },

  fetchMe: async () => {
    const response = await apiClient.get<User>('/auth/me')

    if (!response.ok) {
      set({ error: response.errorMessage || 'Failed to fetch user info' })
      return false
    }

    set({ user: response.data || null, error: null })
    return true
  },

  initialize: () => {
    // Load base URL
    const savedBaseUrl = localStorage.getItem(BASE_URL_KEY)
    if (savedBaseUrl) {
      apiClient.setBaseUrl(savedBaseUrl)
      const normalizedBaseUrl = apiClient.getBaseUrl()
      if (normalizedBaseUrl !== savedBaseUrl) {
        localStorage.setItem(BASE_URL_KEY, normalizedBaseUrl)
      }
      set({ baseUrl: normalizedBaseUrl })
    } else {
      apiClient.setBaseUrl(DEFAULT_BASE_URL)
      set({ baseUrl: apiClient.getBaseUrl() })
    }

    // Load token
    const savedToken = localStorage.getItem(TOKEN_KEY)
    if (savedToken) {
      apiClient.setToken(savedToken)
      set({ token: savedToken, isAuthenticated: true })

      // Fetch user info in background
      get().fetchMe()
    }
  },
}))
"}

