                    filtered[col.name] = datetime.utcnow()
        return filtered

    def _table_or_raise(self, table_name: str) -> Table:
        table = Base.metadata.tables.get(table_name)
        if table is None:
            raise LibrarySeedError(f"Unknown model table: {table_name}")
        return table

